import React from 'react';

function OtherPlayers({ gameState, currentPlayerId }) {
  if (!gameState || !gameState.players) return null;

  const otherPlayers = gameState.players.filter(p => p._id !== currentPlayerId);

  return (
    <div className="other-players">
      <h3>Other Players</h3>
      <div className="players-container">
        {otherPlayers.map((player, index) => (
          <div
            key={player._id || index}
            className={`player-info ${gameState.currentPlayer && gameState.currentPlayer._id === player._id ? 'current-turn' : ''}`}
          >
            <div className="player-name">{player.name}</div>
            <div className="player-card-count">{player.hand ? player.hand.length : 0} cards</div>
            {gameState.currentPlayer && gameState.currentPlayer._id === player._id && (
              <div className="turn-indicator">Their turn</div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

export default OtherPlayers;
